class StatTilesTest {

    @BeforeAll
    static void startToolkit() throws Exception {
        CountDownLatch started = new CountDownLatch(1);
        Platform.startup(() -> {
            Platform.setImplicitExit(false);
            started.countDown();
        });
        assertTrue(started.await(10, TimeUnit.SECONDS));
    }

    @AfterAll
    static void stopToolkit() {
        Platform.exit();
    }

    @Test
    void emptyBeforeImport() throws Exception {
        assertEquals(List.of("—", "—", "—", "—"), fx(() -> values(new StatTiles(), List.of())));
    }

    @Test
    void countsGradedAverageFixesAndReviews() throws Exception {
        List<StudentProgress> students = List.of(
                student("a", GradingStatus.GRADED, true, Map.of("Q1a", 12.0)),
                student("b", GradingStatus.NEEDS_REVIEW, false, Map.of("Q1a", 8.0)),
                student("c", GradingStatus.SKIPPED, false, Map.of()));
        StatTiles tiles = new StatTiles();

        assertEquals(List.of("2/3", "10.0/20", "1", "2"), fx(() -> values(tiles, students)));
        assertTrue(fx(() -> tiles.view().lookup("#needReviewCount").getStyleClass().contains("stat-attention")));
    }

    private static List<String> values(StatTiles tiles, List<StudentProgress> students) {
        tiles.update(new ProgressSnapshot(students.size(), 0, "", "", students, List.of(), List.of()));
        return tiles.view().lookupAll(".stat-value").stream().map(node -> ((Label) node).getText()).toList();
    }

    private static StudentProgress student(String username, GradingStatus status, boolean fixed,
            Map<String, Double> scores) {
        Map<String, QuestionGradingResult.Status> problems = status == GradingStatus.NEEDS_REVIEW
                ? Map.of("Q1a", QuestionGradingResult.Status.EXECUTION_TIMEOUT) : Map.of();
        return new StudentProgress(username, status, true, scores, List.of(),
                fixed ? List.of("Q1a.java was moved into Q1.") : List.of(), List.of(), List.of(), problems);
    }

    private static <T> T fx(Callable<T> action) throws Exception {
        FutureTask<T> task = new FutureTask<>(action);
        Platform.runLater(task);
        return task.get(10, TimeUnit.SECONDS);
    }
}
